{
  "name": "GenICam工业相机",
  "name_en": "GenICam machine vision camera",
  "manufacturer": "",
  "description": "一种遵循 GenICam/GenTL 标准进行图像传输的工业相机或机器视觉相机，用于实验室中的显微成像、样品观察、过程记录和自动化视觉检测，可进行单帧或连续图像采集。",
  "description_en": "An industrial or machine-vision camera that transfers images through the GenICam/GenTL standard. It is used in laboratories for microscopy imaging, sample observation, process documentation, and automated visual inspection, supporting single-frame or continuous image acquisition.",
  "tag_hints": [
    "machine vision camera",
    "GenICam",
    "GenTL",
    "image acquisition",
    "industrial imaging",
    "frame capture",
    "laboratory imaging"
  ],
  "actions": [
    {
      "action_name": "auto-is_valid",
      "description": "检查当前采集会话是否仍然有效",
      "description_en": "Check whether the current acquisition session is still valid"
    },
    {
      "action_name": "auto-add_callback",
      "description": "为相机采集事件添加回调",
      "description_en": "Add a callback for camera acquisition events"
    },
    {
      "action_name": "auto-remove_callback",
      "description": "移除指定的相机采集事件回调",
      "description_en": "Remove the callback for a specified camera acquisition event"
    },
    {
      "action_name": "auto-remove_callbacks",
      "description": "移除全部相机采集事件回调",
      "description_en": "Remove all camera acquisition event callbacks"
    },
    {
      "action_name": "auto-supported_events",
      "description": "获取支持的采集事件类型",
      "description_en": "Get the supported acquisition event types"
    },
    {
      "action_name": "auto-destroy",
      "description": "释放采集资源并结束与相机的连接会话",
      "description_en": "Release acquisition resources and end the camera session"
    },
    {
      "action_name": "auto-num_buffers",
      "description": "获取/设置采集缓冲区数量",
      "description_en": "Get/set the number of acquisition buffers"
    },
    {
      "action_name": "auto-min_num_buffers",
      "description": "获取最小采集缓冲区数量",
      "description_en": "Get the minimum number of acquisition buffers"
    },
    {
      "action_name": "auto-num_filled_buffers_to_hold",
      "description": "获取/设置保留的已填充缓冲区数量",
      "description_en": "Get/set the number of filled buffers to retain"
    },
    {
      "action_name": "auto-num_holding_filled_buffers",
      "description": "获取当前可用的已填充缓冲区数量",
      "description_en": "Get the number of currently available filled buffers"
    },
    {
      "action_name": "auto-data_streams",
      "description": "获取关联的数据流",
      "description_en": "Get the associated data streams"
    },
    {
      "action_name": "auto-remote_device",
      "description": "获取连接的远端成像设备（通常为相机）",
      "description_en": "Get the connected remote imaging device (typically the camera)"
    },
    {
      "action_name": "auto-device",
      "description": "获取关联的本地设备对象",
      "description_en": "Get the associated local device object"
    },
    {
      "action_name": "auto-interface",
      "description": "获取关联的传输接口",
      "description_en": "Get the associated transport interface"
    },
    {
      "action_name": "auto-system",
      "description": "获取关联的传输系统",
      "description_en": "Get the associated transport system"
    },
    {
      "action_name": "auto-is_acquiring_images",
      "description": "获取设备是否正在采集图像",
      "description_en": "Get whether the device is acquiring images"
    },
    {
      "action_name": "auto-is_acquiring",
      "description": "获取设备是否正在采集图像",
      "description_en": "Get whether the device is acquiring images"
    },
    {
      "action_name": "auto-is_armed",
      "description": "获取设备是否已进入采集待命状态",
      "description_en": "Get whether the device is armed for acquisition"
    },
    {
      "action_name": "auto-timeout_on_client_fetch_call",
      "description": "获取/设置客户端取帧超时时间",
      "description_en": "Get/set the client-side fetch timeout"
    },
    {
      "action_name": "auto-timeout_period_on_client_fetch_call",
      "description": "获取/设置客户端取帧超时时间",
      "description_en": "Get/set the client-side fetch timeout period"
    },
    {
      "action_name": "auto-timeout_period_on_update_event_data_call",
      "description": "获取/设置内部事件数据更新超时时间",
      "description_en": "Get/set the timeout period for internal event-data updates"
    },
    {
      "action_name": "auto-timeout_for_image_acquisition",
      "description": "获取/设置图像采集超时时间",
      "description_en": "Get/set the image acquisition timeout"
    },
    {
      "action_name": "auto-thread_image_acquisition",
      "description": "获取/设置图像采集线程对象",
      "description_en": "Get/set the image acquisition thread object"
    },
    {
      "action_name": "auto-statistics",
      "description": "获取图像采集统计信息",
      "description_en": "Get image acquisition statistics"
    },
    {
      "action_name": "auto-start_image_acquisition",
      "description": "开始图像采集",
      "description_en": "Start image acquisition"
    },
    {
      "action_name": "auto-start_acquisition",
      "description": "开始图像采集",
      "description_en": "Start image acquisition"
    },
    {
      "action_name": "auto-start",
      "description": "开始图像采集",
      "description_en": "Start image acquisition"
    },
    {
      "action_name": "auto-try_fetch",
      "description": "在限定时间内尝试获取一帧图像",
      "description_en": "Try to fetch one image frame within the specified timeout"
    },
    {
      "action_name": "auto-fetch_buffer",
      "description": "获取一帧已采集的图像",
      "description_en": "Fetch one acquired image frame"
    },
    {
      "action_name": "auto-fetch",
      "description": "获取一帧已采集的图像",
      "description_en": "Fetch one acquired image frame"
    },
    {
      "action_name": "auto-stop_image_acquisition",
      "description": "停止图像采集",
      "description_en": "Stop image acquisition"
    },
    {
      "action_name": "auto-stop_acquisition",
      "description": "停止图像采集",
      "description_en": "Stop image acquisition"
    },
    {
      "action_name": "auto-stop",
      "description": "停止图像采集",
      "description_en": "Stop image acquisition"
    }
  ]
}

